import{z as d,x as E,o as i,c,q as s,j as l,D as e,d as r,s as t,S as p,b as o}from"./chunks/framework.C8m1ZpeB.js";const R=JSON.parse('{"title":"二次剩余","description":"","frontmatter":{"title":"二次剩余","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/quadratic-residue.md","filePath":"cs/quadratic-residue.md","lastUpdated":1791413859000}'),A={name:"cs/quadratic-residue.md"};function B(b,a,m,u,h,f){const n=E("Mermaid");return i(),c("div",null,[a[2]||(a[2]=s('<h1 id="二次剩余" tabindex="-1">二次剩余 <a class="header-anchor" href="#二次剩余" aria-label="Permalink to &quot;二次剩余&quot;">​</a></h1><div class="epigraph"><p>模 $p$ 的平方剩余由勒让德符号判定，欧拉准则 $a^{(p-1)/2}\\equiv\\pm 1$；模 $n=pq$ 的二次剩余判定与分解一样硬，这是若干比特承诺的老家。</p><footer>—— 据 Gauss；Ireland and Rosen 整理</footer></div><p>上一课<a href="/cs/generator-discrete-log">离散对数</a> 是指数。缺口是<strong>平方</strong>：哪些 \\(a\\) 有 \\(x^2\\equiv a\\pmod p\\)。勒让德 \\((\\frac{a}{p})\\)，二次互反律用来算。模合数 \\(n\\) 的 Jacobi 可多项式计算，却不回答是否真平方——Goldwasser–Micali 等协议吃这一缝。本课不写协议。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(\\mathbb{F}_p^\\times\\) 循环，平方恰一半元素。欧拉：\\(a^{(p-1)/2}\\equiv(\\frac{a}{p})\\pmod p\\)。Tonelli–Shanks 在 \\(p\\bmod 4\\) 等条件下开方。模 \\(n=pq\\)：若知 \\(p,q\\) 可 CRT 开方；不知则 QR 判定等价某些困难假设。<span class="marginnote">术语翻译：Jacobi 符号就是「把勒让德符号按 \\(n\\) 的素因子乘起来」的快捷记号，\\((\\frac{a}{n})=\\prod_i(\\frac{a}{p_i})\\)——它复用勒让德的算法骨架所以多项式时间可算；但乘积等于 \\(1\\) 可能来自两个 \\(-1\\) 相乘抵消，这正是它对真 QR 假阳性的来源。</span>Jacobi \\((\\frac{a}{n})\\) 把勒让德乘起来，可多项式算，但对 QR 有假阳性。</p><p>不要把「平方根模 \\(n\\)」写成 OWF 的唯一例子：它与分解等价（Rabin）。点名。</p><h3 id="jacobi-不是勒让德" tabindex="-1">Jacobi 不是勒让德 <a class="header-anchor" href="#jacobi-不是勒让德" aria-label="Permalink to &quot;Jacobi 不是勒让德&quot;">​</a></h3><p>\\((\\frac{a}{n})=1\\) 仍可能非剩余。写程序时用 Jacobi 当「是否平方」会错。</p><p><span class="marginnote">Gauss 二次互反。Ireland–Rosen 第 5–6 章。Cipolla、Tonelli–Shanks 开方。本课要判别与合数缝隙，不证互反律。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在模 \\(11\\) 列出平方表，核对欧拉准则。<span class="marginnote">数字实例：模 \\(11\\) 时 \\(p-1=10\\)，判 \\(a=5\\) 就算 \\(5^{5}\\bmod 11=1\\)，故 \\(5\\) 是平方剩余（确实 \\(4^2=16\\equiv 5\\)）；判 \\(a=2\\) 得 \\(2^{5}\\bmod 11=-1\\)，故 \\(2\\) 不是——一次幂运算替代了逐个试平方。</span>指出互反律把 \\((\\frac{p}{q})\\) 换成 \\((\\frac{q}{p})\\) 带符号，便于手算。对照 Miller–Rabin：那里用 \\(a^{(n-1)/2}\\) 一类当见证，下一课。</p>',11)),(i(),l(p,null,{default:e(()=>[t(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22a%20mod%20p%22%5D%20--%3E%20EUL%5B%22a%5E%7B(p-1)%2F2%7D%22%5D%0A%20%20EUL%20--%3E%20LEG%5B%22%E5%8B%92%E8%AE%A9%E5%BE%B7%20%C2%B11%20%2F%200%22%5D%0A%20%20N%5B%22a%20mod%20pq%22%5D%20--%3E%20JAC%5B%22Jacobi%20%E6%98%93%E7%AE%97%22%5D%0A%20%20JAC%20--%3E%20GAP%5B%22%E2%89%A0%20%E7%9C%9F%20QR%20%E5%88%A4%E5%AE%9A%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[r("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,"QR 给「比特藏在剩余/非剩余」的经典承诺。后课格密码不再依赖 QR。素性测试用相关的幂，但见证选择不同。本课把平方这一层钉在 DLP 与素性之间。",-1)),(i(),l(p,null,{default:e(()=>[t(n,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22%E5%BE%85%E6%89%BF%E8%AF%BA%E6%AF%94%E7%89%B9%20b%22%5D%20--%3E%20PICK%7B%22b%20%E5%8F%96%200%20%E8%BF%98%E6%98%AF%201%EF%BC%9F%22%7D%0A%20%20PICK%20--%3E%7C0%7C%20R%5B%22%E5%8F%91%E9%9A%8F%E6%9C%BA%E4%BA%8C%E6%AC%A1%E5%89%A9%E4%BD%99%20mod%20n%22%5D%0A%20%20PICK%20--%3E%7C1%7C%20NR%5B%22%E5%8F%91%E9%9A%8F%E6%9C%BA%E9%9D%9E%E5%89%A9%E4%BD%99%20mod%20n%22%5D%0A%20%20R%20--%3E%20LOOK%5B%22%E4%B8%A4%E8%80%85%20Jacobi%20%E9%83%BD%20%3D%201%EF%BC%9A%E5%A4%96%E8%A7%82%E7%9B%B8%E5%90%8C%22%5D%0A%20%20NR%20--%3E%20LOOK%0A%20%20LOOK%20--%3E%20HARD%5B%22%E5%8C%BA%E5%88%86%E5%AE%83%E4%BB%AC%E7%AD%89%E4%BB%B7%E4%BA%8E%E5%88%86%E8%A7%A3%20n%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=s('<p><span class="marginnote">初学者容易把 Jacobi \\(=1\\) 当成「是平方」的判定用；实际上模合数时 \\(+1\\) 既可能是真剩余、也可能是非剩余因子相乘抵消——拿它筛 QR 的程序会系统性出错，这正是「Jacobi 不是勒让德」要钉住的误区。</span></p><p>二次互反：\\((\\frac{p}{q})(\\frac{q}{p})=(-1)^{(p-1)(q-1)/4}\\)（奇素数）。手算勒让德靠它。Tonelli–Shanks 在素数域开方多项式。Rabin 加密：平方模 \\(n\\)，解密开方，与分解等价。GM 承诺用模 \\(n\\) 的 QR 藏一比特，本课不写协议。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证二次互反，不引入高次剩余。不写 Goldwasser–Micali 加密。后课默认：模 \\(p\\) 的 QR 易判；模 \\(pq\\) 的真 QR 难。下一课 Miller–Rabin。</p><p>模 \\(p\\) 的 QR 易判、可开方；模 \\(pq\\) 的真 QR 与分解同级难，Jacobi 却好算——缝隙是承诺方案的老家。欧拉准则的平方链形状，下一课变成 Miller–Rabin 见证。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>模 \\(p\\)：一半平方；欧拉准则给勒让德。</li><li>模 \\(pq\\)：Jacobi 易、真 QR 难；开方与分解等价。</li><li>Jacobi \\(=1\\) 不是剩余的充要条件。</li><li>出处：Gauss；Ireland and Rosen。</li></ul>',7))])}const _=d(A,[["render",B]]);export{R as __pageData,_ as default};
